const input = $input.first().json;
const industry = (input.industry || '').trim();

const industryMap = {
  'artificial intelligence': [
    'Artificial Intelligence',
    'Machine Learning',
    'AI Software',
    'Generative AI',
    'Data Analytics'
  ],

  'software development': [
    'Software Development',
    'Software Company',
    'Web Development',
    'Application Development',
    'IT Services'
  ]
};

const normalizedIndustry = industry.toLowerCase();

const keywords = industryMap[normalizedIndustry] || [industry];

return keywords.map(keyword => ({
  json: {
    ...input,
    searchKeyword: keyword
  }
}));

const items = $input.all();

const companies = items
  .map(item => item.json.linkedinUrl)
  .filter(Boolean);

return [
  {
    json: {
      companies
    }
  }
];

const items = $input.all();

const validTitles = [
  'ceo',
  'chief executive officer',
  'founder',
  'co-founder',
  'co founder'
];

function normalize(text = '') {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

return items
  .filter(item => {
    const data = item.json;

    const title = normalize(
      data.currentTitle ||
      data.headline ||
      ''
    );

    // Keep only CEO / Founder type profiles
    const titleMatch = validTitles.some(t =>
      title.includes(t)
    );

    return titleMatch;
  })
  .map(item => ({
    json: item.json
  }));

const items = $input.all();

function normalize(text = '') {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function getTargetCompany(query = '') {
  let text = normalize(query);

  const prefixes = [
    'chief executive officer at ',
    'co founder at ',
    'founder at ',
    'ceo at '
  ];

  for (const prefix of prefixes) {
    if (text.startsWith(prefix)) {
      return text.slice(prefix.length).trim();
    }
  }

  return text;
}

const ignoredWords = new Set([
  'pakistan',
  'pvt',
  'private',
  'ltd',
  'limited',
  'inc',
  'llc',
  'company',
  'software',
  'solutions',
  'the',
  'and',
  'of'
]);

return items
  .filter(item => {

    const data = item.json;

    const targetCompany = getTargetCompany(
      data.sourceQuery || data.sourceCompany || ''
    );

    const companyWords = targetCompany
      .split(' ')
      .filter(word =>
        word.length >= 3 &&
        !ignoredWords.has(word)
      );

    const profileText = normalize([
      data.headline || '',
      data.currentTitle || '',
      data.currentCompany || '',
      ...(data.experience || []).map(x => x.position || '')
    ].join(' '));

    // ALL meaningful company words must appear
    const companyMatches = companyWords.every(word =>
      profileText.includes(word)
    );

    return companyMatches;
  })
  .map(item => ({
    json: item.json
  }));

const data = $json;

// CHANGE THIS to the exact name of the node that produced
// the verified candidates BEFORE Profile Enrichment.
const candidates = $items('Code in JavaScript4');

function normalize(text = '') {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function linkedinId(url = '') {
  const match = String(url).match(/linkedin\.com\/in\/([^/?#]+)/i);
  return match ? match[1].toLowerCase() : '';
}

// Profile URL used as input to enrichment
const enrichedProfileId = linkedinId(
  data.inputUrl || data.profileUrl || ''
);

// Find the SAME person in our pre-enrichment candidates
const originalCandidate = candidates
  .map(item => item.json)
  .find(candidate => {
    return linkedinId(candidate.url || '') === enrichedProfileId;
  });

if (!originalCandidate) {
  return {
    ...data,
    targetCompany: '',
    decisionMakerVerified: false,
    verificationReason: 'Original search candidate could not be matched'
  };
}

const sourceQuery =
  originalCandidate.sourceQuery ||
  originalCandidate.sourceCompany ||
  '';

let targetCompany = normalize(sourceQuery);

const prefixes = [
  'chief executive officer at ',
  'co founder at ',
  'founder at ',
  'ceo at '
];

for (const prefix of prefixes) {
  if (targetCompany.startsWith(prefix)) {
    targetCompany = targetCompany
      .slice(prefix.length)
      .trim();
    break;
  }
}

// Ignore generic/legal/location words
const ignoredWords = new Set([
  'pakistan',
  'pvt',
  'private',
  'ltd',
  'limited',
  'inc',
  'llc',
  'company'
]);

const targetWords = targetCompany
  .split(' ')
  .filter(word =>
    word.length >= 3 &&
    !ignoredWords.has(word)
  );

// Build strong evidence from enriched LinkedIn profile
const evidence = normalize([
  data.summary || '',
  data.headline || '',
  data.currentCompany?.name || '',

  ...(data.currentPositions || []).map(x =>
    `${x.company || ''} ${x.title || ''}`
  ),

  ...(data.experiences || []).map(x =>
    `${x.company || ''} ${x.title || ''}`
  ),

  ...(data.recentArticles || []).map(x =>
    x.text || ''
  )
].join(' '));

const companyMatch =
  targetWords.length > 0 &&
  targetWords.every(word =>
    evidence.includes(word)
  );

return {
  ...data,

  targetCompany,

  decisionMakerVerified: companyMatch,

  verificationReason: companyMatch
    ? 'Target company verified from enriched LinkedIn profile evidence'
    : 'Target company could not be verified from enriched LinkedIn profile'
};

